begin;

do $$
declare
  v_payload jsonb := $subjectskill${"skill_slug":"subject-lesson-design-art","source_skill_name":"art-public-lesson-design","version_label":"v2.0.0","snapshot_hash":"ff7ef23d4eb68137106579019727a3fb35684deee3358b37161c3b9f696d66d8","instructions":"---\nname: art-public-lesson-design\ndescription: Design complete primary, junior-secondary, or senior-secondary visual-art public lessons from verified textbooks, artworks, images, object records, and material conditions. Use for 美术/艺术·美术公开课、优质课、展示课、赛课 involving appreciation and criticism, drawing, painting, printmaking, sculpture, craft, calligraphy or seal carving, design, photography, architecture, digital/media art, folk art, visual communication, or integrated inquiry; requires slow looking, visual evidence, material and technique trials, student intention, process documentation, critique-revision, studio safety, cultural provenance, and image copyright boundaries.\n---\n\n# 美术公开课设计\n\n让学生从慢看和视觉证据出发，按课型进入“解释—质询—修订评述”“试验—构想—制作—观看修订”或“调查—原型—用户/公共反馈—迭代”。教师范画、步骤照做、作品故事、PPT图片和最后展览只能辅助，不能替代学生的视觉判断及与主导模式匹配的修订证据。\n\n## 运行门禁\n\n1. 核对学段、年级、教材版本、单元、课题、学习领域与课时；获得教材页、高清且色彩/比例可靠的作品图、完整作品信息和材料要求。\n2. 当前项目没有美术教材；仅给课题名时先列缺失项，不猜作品作者/年代/尺寸/材质/收藏、图像细节、技法步骤、文化含义或教材任务。\n3. 课前核验材料工具的年龄适切、毒性/过敏、通风、防护、刀具热具和清洁处置；文化遗产、民族民间和宗教图像需核来源、语境、文化主体与复制边界。\n4. 必读 [主流模式](references/mainstream-models.md)、[输出模板](references/output-template.md)、与学段匹配的样例和 [来源边界](references/sources-and-boundaries.md)。\n\n## 工作流\n\n### 1. 建立视觉—材料—意图地图\n\n记录作品/对象元数据、学生能直接看到什么、造型元素（线条、形状、色彩、明暗、肌理、空间等）、形式原理（对比、重复、节奏、均衡、变化统一等）、媒介技法、功能/受众/场合、文化语境、可能解释及证据边界。先看图像/实物，再提供背景；区分观察事实、形式分析、解释和价值判断。\n\n### 2. 诊断视觉与制作起点\n\n用局部观察、比较两作、视觉元素标注、材料小试、构图草图、用户阅读测试或作品归类诊断。避免只问作者生平和术语；识别“画得像才好”“颜色多才美”“照范画最安全”“手工完成即成功”“我喜欢/不喜欢就是评述”等误区。\n\n### 3. 确定核心增长\n\n> 学生从“快速看图、复述背景或照步骤完成”，走向“依据视觉证据形成判断，并在评述、创作或公共设计任务中通过质询/试验/观看者反馈修订，使解释、作品或方案更有依据、更有效”。\n\n目标2—4项，对齐个体观察单、材料实验格、缩略草图、设计说明、过程照片/版本、同伴观看记录、作品修订或证据化评述。\n\n### 4. 选择主导模式\n\n- 欣赏·评述与视觉探究；\n- 造型·表现与观察表达；\n- 材料技法实验与版画/雕塑/工艺；\n- 设计·应用与用户测试；\n- 民间美术/书法/文化遗产研习；\n- 摄影、影视、数字/媒体艺术；\n- 综合·探索与社区/环境项目。\n\n按 [主流模式](references/mainstream-models.md) 选一条主线。美术知识和技能在解决视觉表达问题时显化，不做孤立术语清单，也不以“自由创作”为名取消教学与评价标准。\n\n### 5. 组织原作/图像观看\n\n先给足静默观看和个人标记，再让学生“描述—分析—解释—判断”；每个解释指向作品局部、形式关系或来源资料。裁切、调色、局部放大、复原/临摹/数字重建必须标注；屏幕色差和二维照片不能完整替代原作尺度、材质与空间体验。\n\n### 6. 按主导模式选择修订证据链\n\n- **鉴赏/评述型**：慢看→D-A-I-E或同类证据框→至少两种解释→分批语境资料→视觉/来源质询→评述V1→有边界V2；不强塞材料制作。\n- **造型/设计创作型**：正式制作前做目标相关的视觉或材料/技法变量试验，形成至少两种构想并说明选择→作品/原型V1→观看者/用户或结构测试→V2。教师只示范关键操作和安全，不生成唯一成品。\n- **摄影/数字/公共项目型**：调查/授权→至少两种叙事或方案→分镜/原型V1→受众/现场/可用性及伦理版权检查→迭代V2→发布/维护边界。\n\n三条链目标等价：都必须保留个人初始判断/方案、外部证据反馈和实质修订，但产物不得跨课型机械同构。\n\n### 7. 复核\n\n- 图像元数据、色彩比例、作者年代材质收藏和文化事实是否可核；\n- 是否先有学生观看证据，再有背景知识和教师解释；\n- 每人是否完成与主导模式匹配的观察/判断、初版、反馈和修订；创作/项目课另核试验、构想、制作/原型，而非少数学生布展；\n- 评价是否对齐意图、视觉选择、材料控制和变化，不以像不像/整洁/天赋为唯一标准；\n- 是否有视觉、精细动作、色觉、材料敏感和表达差异的目标等价路径；\n- 材料工具、文化挪用、肖像隐私、AI/数字图像和版权边界是否落实。\n\n## 输出要求\n\n严格使用 [输出模板](references/output-template.md) 十三部分，Markdown 输出。样例只示范结构和视觉证据链；证据不足时停止完整生成并列出教材、图像、材料和安全的最小补充清单。","input_contract":{"format":"art_public_lesson_input_v1","required":["stage","subject","grade","volume","unit","topic","lesson_type"],"supported_stages":["小学","初中","高中"],"evidence_gate":"verified_textbook_artwork_images_materials_and_safety_required"},"output_contract":{"format":"art_public_lesson_markdown_v1","required_sections":["课程基本信息","单元与教材定位","作品、视觉语言与文化分析","学情与视觉制作起点","核心增长与目标—任务—证据","重难点与视觉实践链","主导模式与公开课主线","图像材料、工具、安全与版权","观察、试验、草图与评价工具","教学流程","板书与作品呈现","量规、差异化与作业","反思与核验"],"lesson_flow_required":["环节功能/对应目标","作品/图像/材料编号","观看/制作任务","个体先行证据","合作必要性","教师行为与示范边界","学生看想试做说改行动","产出","不同解释/方案","典型困难","评价与反馈分支","视觉语言/材料/文化落点","工具安全/版权边界","阶段成果与过渡","时间核算"]},"source_metadata":{"source_package":"art-public-lesson-design","source_kind":"repository_skill_source","source_file_count":8,"runtime_reference_count":6,"source_skill_hash":"b4e6453134c4b2694bd0827895211188a67f36876d8d150ab01b85abe06a3c20"},"references":[{"path":"references/mainstream-models.md","name":"美术公开课主流教学模式","description":"七类美术模式、视觉证据、材料设计实践和失败信号","media_type":"text/markdown","content":"# 美术公开课主流教学模式\n\n| 主导模式 | 核心循环 | 必须证据 | 失败信号 |\n|---|---|---|---|\n| 欣赏·评述/视觉探究 | 静默观看→可见事实→形式分析→多种解释→语境资料→证据化判断→迁移比较 | 个体观察单、局部指证、比较矩阵、修订评述 | 讲作者故事；教师宣布“标准感受”；图片走马灯 |\n| 观察与造型表现 | 多角度观察→比例/结构/空间或特征提取→媒介小试→草图→表现→对照观察修订 | 观察图、试验格、草图/成品差异 | 只看范画；以画得像为唯一标准 |\n| 材料技法实验 | 材料属性→安全示范→变量试验→效果记录→意图匹配→制作→耐久/结构测试→修订 | 材料实验矩阵、工艺流程、失败样片、作品修订 | 步骤手工课；材料越多越好；失败被丢弃 |\n| 设计·应用 | 用户/场景→需求与约束→案例视觉分析→多草案→原型→可读/可用测试→迭代→发布规范 | 需求表、草图、原型、用户反馈、版本差异 | 装饰等于设计；教师审美代替用户证据 |\n| 民间/传统艺术研习 | 原作/器物细看→材料技艺→功能场合→文化主体/象征证据→适切体验→创新边界→反思 | 来源卡、形式/功能分析、工艺体验、文化说明 | 把传统图样当素材库；异域化、乱释寓意 |\n| 摄影/数字媒体 | 传播目的→镜头/构图/时间/声音/编辑实验→拍摄制作→观看者测试→版权隐私→修订 | 分镜/拍摄表、素材授权、粗剪/终版 | 滤镜效果替代视觉表达；偷拍；AI图不标注 |\n| 综合·探索/公共艺术 | 社区/环境问题→现场观察→利益相关者→艺术方法→方案→原型/实施→公共反馈→维护反思 | 调查记录、方案、模型、许可、公众反馈 | 做展板不调查；美化掩盖问题；无维护与授权 |\n\n## 学段适配\n\n- **小学1—2年级**：感官发现、点线面色彩肌理、游戏化造型和生活标识；材料安全、短时多试，不用成人范画控制成品。\n- **小学3—5/6年级**：增加观察写生、形式原理、民间美术、设计应用和综合探索；能说明选择并接受观看反馈。\n- **初中**：加强图像识读、空间/结构、风格文化、设计流程、媒介实验和批评修订；作品差异不是偏离标准。\n- **高中**：依据美术鉴赏、绘画、中国书画、雕塑、设计、工艺、现代媒体等模块，提升描述—分析—解释—评价、研究、策展和独立创作论证。\n\n## 视觉证据规则\n\n- **描述**只说可见/可测：位置、数量、色彩、形状、尺度、材质痕迹。\n- **分析**说明元素怎样组织：对比、重复、节奏、均衡、空间、视觉动线。\n- **解释**连接主题/功能/情感/文化，须有形式或来源证据，并允许替代解释。\n- **评价**依据明确标准判断效果，同时说明视角与边界；“我喜欢”可以是起点，不是终点。\n- 图片不是原作本身；裁切、色差、比例、屏幕亮度会改变判断。AI生成、复原、临摹和二创必须标识。","content_hash":"6afd74c1248abb1cfbcc72481c5077bcace087ac37bdf6baa57f7f6213ed6044","load_mode":"always","max_chars":1220,"sort_order":10,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"discipline_reference"}},{"path":"references/output-template.md","name":"美术公开课完整输出模板","description":"十三部分教案、作品分析、试验草图评改、安全版权与质量约束","media_type":"text/markdown","content":"# 美术公开课完整输出模板\n\n## 一、课程基本信息\n学段/年级、教材版本、单元/课题、学习领域、课型时长、主导模式、课时、教材/作品图像/材料证据状态、待核项。\n\n## 二、单元与教材定位\n单元观念、前后视觉/材料经验、本课功能、教材正文/图例/任务/评价。仅标题不得完整生成。\n\n## 三、作品、视觉语言与文化分析\n每件作品/对象编号，作者/文化主体、题名、年代、尺寸、材质技法、收藏/地点、图像来源/许可、完整/局部/复原状态；列可见事实、造型元素、形式原理、媒介痕迹、功能/受众/场合、解释及替代解释、文化边界。图像色彩比例待核须明示。\n\n## 四、学情与视觉制作起点\n观察、图像识读、造型元素、空间/结构、材料控制、设计思维、文化认识、评价语言和视觉/色觉/精细动作差异；2—4分钟个体诊断及分支。\n\n## 五、核心增长与目标—任务—证据\n一句增长；2—4项目标对应主导模式的个体证据和成功标准：鉴赏型用观察、解释假设、来源权重、评述V1/V2；创作型用试验、草图、作品/原型V1/V2；媒体/公共项目型用调查授权、分镜/方案、受众测试与迭代。不得只写“提高审美、培养创造力”。\n\n## 六、重难点与视觉实践链\n按主导模式选择一条并写不能推出：\n\n- 鉴赏型：`慢看→描述→分析→多种解释→语境核证→质询→评述V1/V2→迁移`；\n- 创作/设计型：`观察/需求→视觉或材料试验→多构想→选择→制作/原型V1→观看/用户/结构测试→V2→迁移`；\n- 媒体/公共项目型：`现场/受众调查→授权与约束→多方案/分镜→原型V1→受众/伦理/可用性测试→V2→发布维护边界`。\n\n## 七、主导模式与公开课主线\n模式理由、核心视觉/设计问题、最终作品或评述、原作观看功能、合作必要性、教师示范边界、学习性亮点与删除的表演/装饰环节。\n\n## 八、图像材料、工具、安全与版权\n图像元数据和显示方式；纸张颜料黏合剂泥材刀具热具/数字设备的规格、数量、过敏毒性/通风/PPE、刀具管理、清洁废弃；轮换、无障碍、版权、肖像/场地许可、AI标识和无设备替代。\n\n## 九、观察、试验、草图与评价工具\n按课型提供等价工具：鉴赏型用视觉证据表、局部标注、解释比较、来源权重、质询与评述V1/V2；创作型用视觉/材料实验矩阵、至少两幅缩略草图、意图/需求卡、制作检查、观看表和作品V1/V2；媒体/公共项目型用调查/授权、分镜/方案、原型、受众/伦理/可用性反馈和迭代表。不得预填唯一解释、构图或标准成品。\n\n## 十、教学流程\n每环写功能、作品/材料编号、观看/制作任务、个体先行、合作必要性、教师行为和示范边界、学生看/想/试/做/说/改、产出、不同解释/方案、典型困难、反馈分支、视觉语言/材料/文化落点、安全、阶段成果/过渡、时间。所有课型必须有“个体初版→外部证据反馈/质询→实质修订”；只有创作/设计课强制视觉/材料试验与多构想，鉴赏课不得为满足格式硬塞手工。\n\n## 十一、板书与作品呈现\n动态呈现视觉证据—形式关系—解释/表达/功能及初版到修订；创作课补材料选择与草图，项目课补受众反馈。展陈标作品信息、过程和学生说明，不按成人审美只展示少数“漂亮作品”。\n\n## 十二、量规、差异化与作业\n至少四维3级：观察证据、形式/材料选择、意图/需求、技法控制、创意发展、文化理解、反馈修订。提供放大/触觉/高对比/非颜色编码、大柄工具/预裁材料、口述/数字/拼贴等目标等价路径。作业说明材料安全、预计时长、版权隐私和无设备替代。\n\n## 十三、反思与核验\n收集个体观察、初版、反馈与修订；创作课另收试验/草图，项目课另收调查/原型。记录3类风险，核验教材、作品元数据、图像色彩比例、文化解释、材料安全、清理、许可和版权。\n\n## 硬约束\n- 不以教师范画或统一步骤制造同款作品。\n- 不用“像不像、干净、漂亮”作为唯一标准，不以手巧/天赋给学生排序。\n- 不先讲背景/寓意后让学生在图中找答案；解释必须基于视觉或来源证据。\n- 不虚构作品信息、传统纹样寓意、技法来源和文化共识。\n- 不忽略材料工具、过敏通风、肖像隐私、AI生成标识和图像版权。","content_hash":"2b1282514fd21e3d739c33b254ffe724783cf42431fb4cf9886989c6efebdbee","load_mode":"always","max_chars":1721,"sort_order":20,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"discipline_reference"}},{"path":"references/excellent-example-primary.md","name":"小学美术优秀教案样例","description":"基于真实精品课题重构的标识视觉识读、用户测试与修订示范","media_type":"text/markdown","content":"# 小学美术优秀教案参考样例\n\n> 依据2024部级精品课真实课题“一年级《身边的标识》”及义务教育艺术课标机制原创重构，不复刻获奖教案。正式实施须补当前教材图例，并实地核验校园标识、拍摄许可和安全位置。\n\n## 一、课程基本信息\n| 字段 | 内容 |\n|---|---|\n| 学段/年级 | 小学一年级 |\n| 课题 | 身边的标识 |\n| 学习领域/时长 | 设计·应用，40分钟 |\n| 主导模式 | 设计·应用 |\n| 真实任务 | 为班级一种低风险公共需要设计容易看懂的标识 |\n| 证据状态 | 课题可核；教材图例与校园真实标识待提供/核验 |\n\n## 二、单元与教材定位\n本课在点、线、形、色和生活观察基础上，理解标识以简明视觉信息帮助人行动；后续连接色彩、图形概括和公共设计。只设计“图书归还、轻声阅读、物品分类”等低风险用途，不制作消防、疏散、交通、医疗等可能被误用的正式安全标识。\n\n## 三、作品、视觉语言与文化分析\n- 选3—5个经核真实标识，记录拍摄地点/机构、用途、许可、完整/局部状态。\n- 学生先说看见的形状、颜色、图像、文字及位置，再推测用途；不能因红色就一律断言危险。\n- 设计变量：图形是否一眼可辨、背景对比、远近尺度、文字依赖、摆放位置；颜色不是唯一编码。\n- 标识效果由具体用户和场景决定，“漂亮”不自动等于清楚。\n\n## 四、学情与视觉制作起点\n学生会看标识但容易画成复杂故事、依赖文字，或照抄范例。诊断3分钟：看两张经核标识，个人圈第一眼看到的形/色并猜用途，写“我看到___所以暂猜___”。读写起点不同者可指图口述。\n\n## 五、核心增长与目标—任务—证据\n**核心增长**：从画一张漂亮小画，走向为特定用户/场景提炼关键信息，用图形、对比和简化设计，接受可读性测试并修订。\n\n| 目标 | 任务 | 个体证据 | 标准 |\n|---|---|---|---|\n| 识读 | 标识慢看 | 个人视觉证据卡 | 观察与推测分开 |\n| 概括 | 物品/行动三步简化 | 3格实验 | 保留识别特征、减少无关细节 |\n| 设计 | 两幅小草图 | 个体A/B方案及选择 | 对应用户/场景，不照范画 |\n| 修订 | 远看/遮字测试 | V1—反馈—V2 | 根据观看者证据调整 |\n\n## 六、重难点与视觉实践链\n`看真实标识→描述/推测→图形简化试验→用户/场景→两草图→选择制作→远看/遮字/灰度测试→反馈修订→说明`。难点是简洁与可识别的平衡。课堂作品不具有正式安全效力。\n\n## 七、主导模式与公开课主线\n“陌生观看者能否在3秒内说出用途”贯穿。教师示范同一物品从复杂到简化的思考，不画最终标识。合作只用于观看测试；每人独立做两案和修订。\n\n## 八、图像材料、工具、安全与版权\n经许可标识照片/实物观察、纸张、粗细笔、可移胶；剪刀若使用按一年级圆头剪和学校规则。禁止学生到车道、消防设施等危险处拍摄，不复制官方安全标识作为装饰。色觉/低视力学生用形状、边框、明暗与触觉线，不以颜色为唯一信号。学生作品不贴真实姓名和位置隐私。\n\n## 九、观察、试验、草图与评价工具\n| 阶段 | 用户/场景 | 必须看懂什么 | 图形实验 | 草图A/B | 3秒测试回答 | 问题 | V2修改 |\n|---|---|---|---|---|---|---|---|\n|  |  |  |  |  |  |  |  |\n\n测试包括远看、遮住文字、灰度/非颜色判断；不预填标准图案。\n\n## 十、教学流程\n### 环节1｜观察不是猜故事（3分钟）\n个人看标识先说形色位置，再猜用途。混写者用两栏卡重写。\n\n### 环节2｜什么让人一眼看懂（6分钟）\n比较经核清晰/复杂案例，学生圈识别特征、对比和文字依赖。教师不把某颜色定义成唯一意义。\n\n### 环节3｜三步视觉简化试验（6分钟）\n每人把同一个低风险班级物品/行动画成“观察轮廓—只删除一类次要细节—保关键特征”三格，记录本轮唯一改变的是细节量；伙伴只说仍看出什么，不代画。若同时换颜色/构图，不将识别变化单独归因于简化。\n\n### 环节4｜界定用户并画A/B草图（7分钟）\n选择图书归还/轻声阅读/物品分类，写用户、位置、行动；每人画两种明显不同方案。只有一案者不得进入成品；照教师示例者换布局或符号逻辑。\n\n### 环节5｜制作V1（7分钟）\n学生依据选择理由制作，教师巡视对比、尺度、简化和安全用具；不替学生描线上色。\n\n### 环节6｜三种观看测试与V2（7分钟）\n同伴在未知题意下3秒看、远看、遮字/非颜色看，记录“我以为___，因为___”。作者只选一至两项视觉问题修订V2；测试者不说“我喜欢的颜色”。\n\n### 环节7｜展签与迁移（4分钟）\n每人写/说：`为___用户在___场景，我用___；测试者因___误读，我改___；它不能当正式___标识。`按过程和修订展示，不只挑漂亮作品。\n\n**总时间：3+6+6+7+7+7+4=40分钟。**\n\n## 十一、板书与作品呈现\n```text\n看见：形 / 色 / 图 / 字 / 位置 → 再推测用途\n用户 + 场景 + 行动\n简化 ≠ 随便；清楚 = 识别特征 + 对比 + 合适尺度\nA/B → V1 → 3秒/远看/遮字测试 → V2\n课堂作品不是正式安全标识\n```\n\n## 十二、量规、差异化与作业\n| 维度 | 3级 | 2级 | 1级 |\n|---|---|---|---|\n| 观察 | 事实与推测分开 | 有观察 | 只猜故事 |\n| 设计 | 用户场景明确、图形简洁可辨 | 基本可读 | 复杂小画/照抄 |\n| 测试 | 三种观看证据并修订 | 有同伴反馈 | 只问好不好看 |\n| 表达 | 能解释选择和非正式边界 | 能说用途 | 只说漂亮 |\n\n精细动作困难者用预裁形状拼贴/粗柄工具，低视力者用大幅高对比/触觉，色觉差异者用形状明暗，语言困难者口述展签。作业拍摄需家长/学校许可；默认纸上记录家中一个包装标识的可见事实和用途推测，10分钟。\n\n## 十三、反思与核验\n- 收集观察卡、简化实验、A/B、V1/V2、观看记录。\n- 风险：颜色刻板、范画复制、课堂标识被误贴；用多编码、两案、明确非正式/课后回收纠偏。\n- 核验教材、照片来源/场地许可、标识真实用途、材料安全和作品隐私。\n- 下一课迁移到校园导向或包装图形，但正式应用需专业/校方审核。","content_hash":"1b846bc4d2a15b430cc3fff519a9b1977eaa336a6d89ba064d9a2c0ca9fc64a6","load_mode":"always","max_chars":2671,"sort_order":30,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"discipline_reference","stages":["小学"]}},{"path":"references/excellent-example-junior.md","name":"初中美术优秀教案样例","description":"剪纸视觉形式、材料变量、文化来源与结构修订示范","media_type":"text/markdown","content":"# 初中美术优秀教案参考样例\n\n> 依据义务教育美术“欣赏·评述”和民间美术学习机制原创重构，题为“剪纸中的重复与变化”。不对应某册教材，也不预设某纹样寓意。正式实施须补教材图例、权威馆藏/传承资料和材料安全信息。\n\n## 一、课程基本信息\n| 字段 | 内容 |\n|---|---|\n| 学段/年级 | 初中七年级 |\n| 课题 | 剪纸中的重复与变化 |\n| 学习领域/时长 | 欣赏·评述 + 造型·表现，45分钟 |\n| 主导模式 | 民间/传统艺术研习（辅以材料实验） |\n| 核心问题 | 剪刻、折叠与连接怎样形成既统一又有变化的视觉节奏？ |\n| 证据状态 | 教材/作品/寓意均待核，不从网图编文化故事 |\n\n## 二、单元与教材定位\n本课承接形状、正负形、重复/变化经验，通过原作观看和纸张实验理解剪纸的视觉与工艺关系；后续可连接民间美术功能、现代视觉设计。不是“照老师剪一个吉祥图案”的手工课。\n\n## 三、作品、视觉语言与文化分析\n- 选2—3件来源可追的馆藏/传承作品，填写作者/地区/年代（若可知）、尺寸、纸材、技法、用途/场合、收藏和图像许可；未知写未知。\n- 先描述正负形、连接点、对称/重复/变化和视觉动线，再结合可靠资料解释功能/文化。\n- 图案相似不自动代表同一寓意；“吉祥、驱邪”等必须对应具体地区/场合/来源，不泛化全中国剪纸。\n- 学生体验可以借鉴结构原理，但不得宣称复刻某传承人作品或代表某群体传统。\n\n## 四、学情与视觉制作起点\n学生可能把剪纸等同“红纸+对称+吉祥”，忽视负形/连接和地域差异；制作时先画复杂图案，剪断后归因手不巧。诊断4分钟：看经核作品局部，每人描一处正形/负形和连接，写观察/解释两栏。直接写寓意者须给来源或降为假设。\n\n## 五、核心增长与目标—任务—证据\n**核心增长**：从识别“好看的传统图案”，走向用视觉/工艺证据分析重复、变化、正负形和连接，并通过材料试验形成有个人意图的结构设计和修订。\n\n| 目标 | 任务 | 个体证据 | 标准 |\n|---|---|---|---|\n| 欣赏评述 | 原作慢看 | 观察—分析—解释卡 | 视觉事实与文化解释分开 |\n| 工艺理解 | 连接/折叠试验 | 失败样片+记录 | 能解释为何断裂/展开 |\n| 创意设计 | 两种结构草图 | A/B与选择理由 | 借鉴原理不复制图案 |\n| 修订 | 展开/悬挂/观看测试 | V1/V2 | 根据结构/视觉证据修改 |\n\n## 六、重难点与视觉实践链\n`原作慢看→正负形/重复变化→来源语境→纸张连接实验→两草图→制作V1→展开结构测试/观看反馈→修订V2→文化说明`。难点是把工艺限制变为视觉选择。\n\n## 七、主导模式与公开课主线\n以“剪开还能连在一起吗、重复中哪里变化”贯穿。教师只示范安全持剪、折/剪关系与连接测试，不画成品。学生失败样片是证据，不丢弃。合作只做未知意图的观看和结构测试。\n\n## 八、图像材料、工具、安全与版权\n经核图像、纸张、铅笔、垫板、圆头/适龄剪刀；刻刀仅在校规允许、教师资质和一对一管理下使用，本样例默认不用。核纸张过敏/粉尘，保持通道和碎纸回收。精细动作困难者用预切纸条、撕纸/拼贴或数字正负形工具。传统图像不下载无源网图，不公开复制销售。\n\n## 九、观察、试验、草图与评价工具\n| 作品/样片 | 可见事实 | 形式分析 | 来源支持的解释/未知 | 折/剪变量 | 展开结果 | 连接失败点 | 下一版修改 |\n|---|---|---|---|---|---|---|---|\n|  |  |  |  |  |  |  |  |\n\n草图必须标折线、剪除区、保留连接和重复/变化位置。\n\n## 十、教学流程\n### 环节1｜慢看：先不讲寓意（4分钟）\n静默观看经核作品，个人描正负形/连接。把红色直接等同吉祥者改为“我看见红色；具体意义待来源”。\n\n### 环节2｜形式关系与多种解释（6分钟）\n比较两作重复、变化、对称、节奏；学生以局部指证。教师后置提供地区/场合/用途资料，区分可核/未知/解释。\n\n### 环节3｜纸张连接小试（7分钟）\n每人做三格变量试验：连接宽度/位置或折叠层数（一次只变一项），展开记录。断裂样片贴表而非丢弃；没有断裂者做悬挂/轻拉测试并记录限度。\n\n### 环节4｜两种构想与意图（6分钟）\n学生为“重复中的一个变化”画A/B，标正负形和连接；选择一案说明视觉节奏和技术可行性。不允许照教师/原作轮廓复刻。\n\n### 环节5｜制作V1（9分钟）\n按安全规则制作，教师只问“这条连接承担什么、变化在哪里”，不替剪。材料或工具困难者走等价拼贴/数字路径。\n\n### 环节6｜展开/悬挂与无题观看（7分钟）\n先结构测试，再让同伴不看说明指出视觉重复、变化和可能薄弱处；反馈必须指作品位置。作者形成V2修补/重剪局部或调整呈现，并保留V1/失败样。\n\n### 环节7｜展签与文化边界（6分钟）\n个人写：`我从作品中观察到___形式，不直接复制___；我用___试验解决___；V2改___；关于文化意义，可核的是___，仍未知___。`\n\n**总时间：4+6+7+6+9+7+6=45分钟。**\n\n## 十一、板书与作品呈现\n```text\n观察事实 → 形式：正/负形、重复/变化、连接 → 来源语境 → 有边界解释\n材料试验（一次一变量）→ 失败样片 → A/B → V1 → 结构/观看测试 → V2\n相似图案 ≠ 固定寓意；体验 ≠ 复刻传统\n```\n\n## 十二、量规、差异化与作业\n| 维度 | 3级 | 2级 | 1级 |\n|---|---|---|---|\n| 视觉分析 | 以局部证据分析形式 | 能描述元素 | 只背寓意 |\n| 材料试验 | 控制变量、保留失败并解释 | 有试验 | 直接照步骤成品 |\n| 创意/结构 | 意图、正负形、连接一致 | 基本完整 | 复制或易断无理由 |\n| 文化边界 | 来源/未知清楚 | 知道需查证 | 泛化/编寓意 |\n\n低视力者用大幅高对比/触觉凸线，色觉不以红色为唯一判断，精细动作困难者走拼贴/数字，阅读困难者口述展签。作业从权威馆藏找一件剪纸，只做视觉事实—来源—未知三栏，不要求在家使用刀具，15分钟。\n\n## 十三、反思与核验\n- 收集观察卡、变量试验/失败样、A/B、V1/V2、展签。\n- 风险：文化泛化、手巧排名、失败丢弃；用来源表、意图/证据量规、失败档案纠偏。\n- 核验作品元数据、图像许可、文化解释、剪具安全、碎纸处置和学生作品传播。\n- 下一课迁移到其他镂空/印制艺术，比较材料与功能差异。","content_hash":"367186d2592eed4cbbe0549732bfc29192d55de138580b7e484531cb24fddd0a","load_mode":"always","max_chars":2757,"sort_order":40,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"discipline_reference","stages":["初中"]}},{"path":"references/excellent-example-senior.md","name":"高中美术优秀教案样例","description":"城市图像D-A-I-E识读、语境核证和有限评述示范","media_type":"text/markdown","content":"# 高中美术优秀教案参考样例\n\n> 依据普通高中美术“美术鉴赏”图像识读机制原创重构，主题为“同一城市，谁的视角”。不对应某册教材或特定作品。正式实施须由教师提供教材选作、高清图像、完整元数据与城市史来源。\n\n## 一、课程基本信息\n| 字段 | 内容 |\n|---|---|\n| 学段/年级 | 高中一年级 |\n| 课题 | 同一城市，谁的视角——城市图像的观看与解释 |\n| 模块/时长 | 美术鉴赏，45分钟 |\n| 主导模式 | 欣赏·评述/视觉探究 |\n| 核心问题 | 画面选择了什么、怎样组织观看，又省略了什么？ |\n| 证据状态 | 必须补当前教材作品A/B及权威元数据，样例不预填作品事实 |\n\n## 二、单元与教材定位\n本课承接描述造型语言的能力，推进到“图像不是透明现实”：视点、取景、尺度、色彩、人物安排、媒介和委托/传播语境共同建构城市形象。后续连接现代媒体、摄影、公共视觉文化或策展。\n\n## 三、作品、视觉语言与文化分析\n为作品A/B分别建立身份证：作者、题名、年代、尺寸、媒介、收藏、创作/委托、展示/传播、高清图来源与裁切色差。学生先观察，再分析构图、视点、尺度、色彩、光、人物/建筑关系、空白/遮挡；解释“理想化、纪实、权力、日常”等须有视觉和来源证据，不由教师预设。图像省略不自动等于作者故意隐瞒，需区分画面未呈现与动机推断。\n\n## 四、学情与视觉制作起点\n学生易把画面当现场照片，先读标题说明再找结论，或用“真实/不真实”二分评价。诊断4分钟：对一张暂隐标题/作者的经核图像写三条可见事实、一条解释和一条不确定；混写者用D-A-I-E（描述/分析/解释/评价）颜色以外的符号重新标。\n\n## 五、核心增长与目标—任务—证据\n**核心增长**：从把城市图像当现实窗口，走向以视觉与语境证据分析其选择/组织/省略，比较解释并修订有边界判断。\n\n| 目标 | 任务 | 个体证据 | 标准 |\n|---|---|---|---|\n| 图像识读 | D-A-I-E慢看 | 个人证据单 | 层级清楚、指向局部 |\n| 比较解释 | A/B矩阵 | 个人比较句 | 同指标比较视觉选择 |\n| 语境核证 | 来源包 | 证据权重卡 | 区分作品事实、评论和推断 |\n| 评述修订 | 同行质询 | 初稿/修订稿 | 缩小过度动机和真实断言 |\n\n## 六、重难点与视觉实践链\n`隐去标签慢看→描述/分析→提出解释→A/B同指标比较→补作者/委托/传播语境→权衡证据→反例/省略质询→修订评述→当代图像迁移`。难点是省略和意图推断边界。\n\n## 七、主导模式与公开课主线\n每次信息释放改变解释：无标签图→比较图→元数据/语境包→反例。最终成果为300字以内有视觉指证和不确定性的个人短评；公开展示不是教师“讲名画”。\n\n## 八、图像材料、工具、安全与版权\n高清合法图像A/B、局部放大C、元数据和语境短文，逐项标完整/裁切、色彩管理、尺寸比例、许可。投影屏幕说明色差，提供纸质高对比/放大、文字图像描述和屏幕阅读兼容材料。不得把当代街拍中可识别人脸/住址作为材料；AI修复/重建必须标注。\n\n## 九、观察、试验、草图与评价工具\n| 层级 | 作品A局部证据 | 作品B局部证据 | 同/异 | 当前解释 | 来源包支持/限制 | 替代解释/仍未知 | 修订 |\n|---|---|---|---|---|---|---|---|\n| 描述/分析/解释/评价 |  |  |  |  |  |  |  |\n\n评述框：主张—视觉证据—语境证据—推理—替代解释/边界。\n\n## 十、教学流程\n### 环节1｜无标签慢看（4分钟）\n个人D-A-I-E；教师不讲作者年代。把“作者想表现”写描述栏者移到解释并标待证。\n\n### 环节2｜视觉动线与选择（7分钟）\n学生沿构图、视点、尺度、色光、人/物关系标局部，写眼睛先后看哪里及证据。大屏缩放不可裁掉关键边缘。\n\n### 环节3｜A/B同指标比较（7分钟）\n每人先用三项共同指标比较，再小组互补。不能用A的色彩对B的历史背景作错位比较。\n\n### 环节4｜分批释放语境资料（7分钟）\n提供元数据、创作/委托、展示传播短文，学生给“直接支持/间接支持/不能支持”。来源不清材料剔除；标题不等于作者完整意图。\n\n### 环节5｜写初稿与视觉指证（6分钟）\n个人短评必须含两个具体位置和一条语境证据。只写“真实反映城市”者限定为“画面呈现”；直接断言作者动机者补来源或改为“可能”。\n\n### 环节6｜反例质询与修订（7分钟）\n同伴从裁切/媒介、代表性、省略、替代解释、语境来源中提一问；作者保留初稿，用修订符号调整。图中没有某人群只能写“此画面未呈现”，不能证明城市中不存在。\n\n### 环节7｜当代迁移与出口（7分钟）\n分析一张经许可、去身份的城市宣传/平台封面：`选择了___，视觉证据___；省略了___（只指画面）；可能服务___，还需___来源确认。`回扣图像责任。\n\n**总时间：4+7+7+7+6+7+7=45分钟。**\n\n## 十一、板书与作品呈现\n```text\n图像 ≠ 现实本身\nD 可见事实 → A 形式组织 → I 解释（视觉+语境证据）→ E 有标准判断\n选择/视点/尺度/色光/人物安排/媒介\n画面未呈现 ≠ 现实不存在 ≠ 作者故意隐瞒\n初稿 → 质询 → 有边界修订\n```\n\n## 十二、量规、差异化与作业\n| 维度 | 3级 | 2级 | 1级 |\n|---|---|---|---|\n| 图像识读 | 层级清楚、局部指证准确 | 有视觉证据 | 只讲故事/标签 |\n| 比较 | 同指标解释差异 | 有异同 | 罗列两作 |\n| 语境 | 来源权重与限制清楚 | 引用背景 | 背景替代观看 |\n| 修订 | 处理省略/动机/替代解释 | 有修改 | 过度真实/意图断言 |\n\n低视力者使用分区文字描述/触觉构图，高对比；色觉差异者用明度/位置而非色名唯一证据；语言困难者用口述CER。作业选一张有版权许可的公共图像做D-A-I-E与来源卡，不用私人街拍，20分钟。\n\n## 十三、反思与核验\n- 收集个人D-A-I-E、比较矩阵、来源权重、两版短评和迁移。\n- 风险：背景压过观看、画面省略被道德化、投影裁切/色差；用分批信息、推断边界、图像核准纠偏。\n- 核验作品元数据、图像完整性/色彩/比例、委托传播来源、肖像隐私和版权。\n- 下一课迁移到摄影/广告/数字图像，加入编辑与AI生成标识。","content_hash":"f4de02c7aaeb74072c6338c2809546a35046a20624e74ea2392ab95a1bf2b975","load_mode":"always","max_chars":2702,"sort_order":50,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"discipline_reference","stages":["高中"]}},{"path":"references/sources-and-boundaries.md","name":"美术 Skill 来源与边界","description":"义教/高中课标、新教材、作品图像、文化版权与材料安全边界","media_type":"text/markdown","content":"# 美术 Skill 来源与边界\n\n- [教育部《义务教育艺术课程标准（2022年版）》入口](https://www.moe.gov.cn/srcsite/A26/s8001/202204/t20220420_619921.html)：艺术核心素养、欣赏/表现/创造/联系及分学段实践首要依据。\n- [普通高中美术课程标准（2017年版2020年修订）](https://www.pep.com.cn/xw/zt/rjwy/gzkb2020/202205/P020220517518487651706.pdf)：高中图像识读、美术表现、审美判断、创意实践、文化理解及模块依据。\n- [人教版义务教育艺术·美术新教材介绍](https://www.pep.com.cn/xw/zt/hd/12/xjcjs/xx/202409/t20240920_1995561.html)：用于核对大单元、社会人文主题、知识技能暗线和真实生活任务方向，不替代教材正文。\n- [2024年部级精品课名单](https://www.moe.gov.cn/jyb_xxgk/s5743/s5744/A06/202506/W020250624684887950733.pdf)：确认不同版本和课题线索，不反推教案。\n- [人教社《产品设计》教学设计](https://www.pep.com.cn/zzggjc/ys2023/ms/jxsj/202309/P020230901391322694507.pdf)：用于核对职业/高中产品设计的需求、造型与实践方向，不复制流程。\n\n当前项目没有美术教材和授权作品图库。正式生成须提供教材页、高清图像/实物信息和材料条件；样例为依据课标机制与可核课题原创重构。作品元数据优先博物馆、美术馆、艺术家/文化机构、教材和权威出版物；普通网图只作检索线索。图片须标完整/局部、裁切、调色、复原、临摹、AI生成或数字重建；屏幕图不等于原作。\n\n传统/民族民间艺术需尊重文化主体、功能场合、传承语境和知识产权，不凭图案形状编寓意，不将神圣/仪式元素随意商品化。学生肖像、家庭/社区场所拍摄须获许可。材料和工具按厂家安全数据及学校制度核准，避免未知粉尘、有毒溶剂、食物过敏材料和无监管刀具/热具。外部作品、字体、图案、照片、视频和AI素材记录来源、许可及学生修改。","content_hash":"516e3cc87c2cad88ab1acf1f6dfc173a74d97f8bec69a23a8adfcb2742fc1180","load_mode":"always","max_chars":985,"sort_order":60,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"discipline_reference"}},{"path":"agents/openai.yaml","name":"OpenAI Skill 界面配置","description":"源包界面元数据，不进入生成上下文","media_type":"application/yaml","content":"interface:\n  display_name: \"美术公开课设计\"\n  short_description: \"以视觉证据、材料探索、表达意图和作品修订设计分学段美术公开课\"\n  default_prompt: \"请依据教材、作品图像与材料条件设计完整美术公开课。\"","content_hash":"195dccfdc1e1888a89bc3d6dff7c60c685c61cd7d0cf6989d8f37be1dd17f73c","load_mode":"evaluation_only","max_chars":136,"sort_order":70,"metadata":{"source_package":"art-public-lesson-design","runtime_role":"evaluation_only"}}],"skill_description":"完整小学、初中、高中美术公开课设计 Skill：以慢看和视觉证据、材料试验、多构想、表达/设计意图、观看反馈和作品修订组织学习。","match_criteria":{"subjects":["美术"],"lesson_types":["公开课"]}}$subjectskill$::jsonb;
  v_skill_id uuid;
  v_version_id uuid;
begin
  select id into v_skill_id
  from public.hai_work_skills
  where slug = v_payload->>'skill_slug';

  if v_skill_id is null then
    raise exception 'Work Skill 不存在：%', v_payload->>'skill_slug';
  end if;

  if exists (
    select 1 from public.hai_work_skill_versions
    where skill_id = v_skill_id
      and version_label = v_payload->>'version_label'
      and status in ('published', 'archived')
  ) then
    raise exception '同名学科 Work Skill 版本已冻结：%', v_payload->>'version_label';
  end if;

  update public.hai_work_skill_versions
  set status = 'archived', updated_at = now()
  where skill_id = v_skill_id and status = 'published';

  insert into public.hai_work_skill_versions (
    skill_id, version_label, status, prompt_template, default_prompt_template,
    input_contract, output_contract, snapshot_hash, source_metadata, published_at
  ) values (
    v_skill_id,
    v_payload->>'version_label',
    'draft',
    v_payload->>'instructions',
    v_payload->>'instructions',
    v_payload->'input_contract',
    v_payload->'output_contract',
    v_payload->>'snapshot_hash',
    v_payload->'source_metadata',
    null
  )
  on conflict (skill_id, version_label) do update set
    status = 'draft',
    prompt_template = excluded.prompt_template,
    default_prompt_template = excluded.default_prompt_template,
    input_contract = excluded.input_contract,
    output_contract = excluded.output_contract,
    snapshot_hash = excluded.snapshot_hash,
    source_metadata = excluded.source_metadata,
    published_at = null,
    updated_at = now()
  returning id into v_version_id;

  delete from public.hai_work_skill_references where skill_version_id = v_version_id;

  insert into public.hai_work_skill_references (
    skill_version_id, path, name, description, media_type, content,
    content_hash, load_mode, max_chars, sort_order, metadata
  )
  select
    v_version_id, item.path, item.name, item.description, item.media_type,
    item.content, item.content_hash, item.load_mode, item.max_chars,
    item.sort_order, item.metadata
  from jsonb_to_recordset(v_payload->'references') as item(
    path text, name text, description text, media_type text, content text,
    content_hash text, load_mode text, max_chars integer, sort_order integer,
    metadata jsonb
  );

  update public.hai_work_skill_versions
  set status = 'published', published_at = now(), updated_at = now()
  where id = v_version_id;

  update public.hai_work_skills
  set name = '美术公开课设计 Skill',
      description = v_payload->>'skill_description',
      match_criteria = v_payload->'match_criteria',
      is_fallback = false,
      is_enabled = true,
      updated_at = now()
  where id = v_skill_id;

  perform public.hai_recompute_work_module_enabled('subject-lesson-design');
end;
$$;

commit;
